import java.net.*;import java.nio.file.*;
public final class Character720ServerCheck {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS: "+s);}
 public static void main(String[] args)throws Exception{CloudStore.Memory store=new CloudStore.Memory();store.register("a@720.test","test-password-123","New");try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){ServerCheck.base="http://127.0.0.1:"+server.port();String token=Equipment718ServerCheck.login("a@720.test");var s=server.sessions.get(token);ok(!Equipment718ServerCheck.call(token,"character",null).readBoolean(),"New account must select a character");Equipment718ServerCheck.call(token,"appearance",o->{o.writeUTF("Female");o.writeByte(1);o.writeByte(0);o.writeBoolean(false);for(int k=0;k<5;k++)o.writeByte(0);o.writeByte(3);});ok(store.profile(s.id).characterChosen&&s.profile.gender==1&&Equipment718ServerCheck.call(token,"character",null).readBoolean(),"Character choice is stored on the account");s.profile.skin=2;s.profile.wardrobe[6]|=4;s.profile.coins=719;s.profile.shoppingMoney=17;Equipment718ServerCheck.call(token,"gender",o->o.writeByte(0));ok(s.profile.gender==0&&s.profile.skin==0&&s.profile.coins==719&&s.profile.shoppingMoney==17&&(s.profile.wardrobe[6]&4)!=0,"Switching sex keeps wallets and owned wardrobe; unowned target outfit uses starter");int id=Equipment718ServerCheck.call(token,"create",o->{o.writeByte(1);o.writeByte(0);o.writeByte(-1);}).readInt();var room=server.rooms.get(id);Equipment718ServerCheck.call(token,"gender",o->o.writeByte(1));ok(s.profile.gender==1&&room.avatars[0].sex==1&&room.equipmentPending==0,"Waiting room broadcasts gender changes and releases its start guard");synchronized(room){room.strict=false;room.start();}Equipment718ServerCheck.reject(token,"gender",o->o.writeByte(0),"Cannot change character during a battle");ok(s.profile.gender==1,"Rejected change preserves character");}System.out.println("All character 7.2.0 server checks passed");}
}
